#!/usr/bin/env python3
"""Concurrent healthy-path throughput: unchecked / always-dual / BoundaryGuard.

Answers: does BG's higher per-request P50 throttle pipeline throughput under
concurrency? Uses overlapping sliding eth_getLogs ranges on Optimism through
the same proxy/harness paths as S4 (not official agent multi-RPC modes).
"""

from __future__ import annotations

# --- github publish layout (auto-generated by sync_github_publish.py) ---
import sys
from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import argparse
import json
import statistics
import time
import urllib.request
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone
from pathlib import Path

import relayer_proxy_live as harness
from boundaryguard_proxy import ProxyConfig
from hyperlane_identity import DISPATCH_TOPIC, normalize
from strong_accept_suite import CALL_CU, LOG_CU


ROOT = _GITHUB_ROOT
DATA = DATA / "strong_e2e"
OUT = DATA / "concurrent_throughput.json"
MESSAGES = DATA / "hyperlane_messages.jsonl"

OP_CFG = {
    "primary": "https://mainnet.optimism.io",
    "boundary": "https://optimism.drpc.org",
    "repair": "https://op-pokt.nodies.app",
}
ARCHIVE = [
    "https://optimism.drpc.org",
    "https://optimism.gateway.tenderly.co",
    "https://op-pokt.nodies.app",
    "https://optimism-mainnet.public.blastapi.io",
]


def rpc_url(url: str, method: str, params: list, timeout: float = 30.0) -> dict:
    payload = {"jsonrpc": "2.0", "id": 1, "method": method, "params": params}
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode(),
        headers={"content-type": "application/json"},
    )
    t0 = time.time()
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            body = resp.read()
            data = json.loads(body)
            outcome = "ok" if "error" not in data else "rpc_error"
            return {
                "outcome": outcome,
                "result": data.get("result"),
                "latency_ms": (time.time() - t0) * 1000,
                "bytes": len(body),
                "error": data.get("error"),
            }
    except Exception as exc:  # noqa: BLE001
        return {
            "outcome": "transport_error",
            "result": None,
            "latency_ms": (time.time() - t0) * 1000,
            "bytes": 0,
            "error": f"{type(exc).__name__}: {exc}",
        }


def load_queries(n: int, width: int) -> tuple[str, list[dict]]:
    rows = []
    with MESSAGES.open() as handle:
        for line in handle:
            row = json.loads(line)
            if row.get("chain") != "optimism" or not row.get("is_delivered"):
                continue
            rows.append(row)
    rows.sort(key=lambda r: int(r["origin_block_height"]))
    mid = len(rows) // 2
    picks = rows[mid : mid + n]
    mailbox = normalize(picks[0]["origin_mailbox"])
    queries = []
    for row in picks:
        start = int(row["origin_block_height"])
        end = start + width - 1
        queries.append(
            {
                "fromBlock": hex(start),
                "toBlock": hex(end),
                "address": mailbox,
                "topics": [DISPATCH_TOPIC],
            }
        )
    return mailbox, queries


def run_mode(
    mode: str,
    queries: list[dict],
    *,
    concurrency: int,
    proxy_url: str | None,
    dual_fallback: str,
    proxy=None,
) -> dict:
    latencies: list[float] = []
    ok = 0
    fail = 0
    log_calls = 0
    bytes_total = 0
    stats0 = dict(proxy.stats) if proxy is not None and mode == "boundaryguard" else None

    def one(q: dict) -> dict:
        nonlocal log_calls, bytes_total
        t0 = time.time()
        if mode == "unchecked":
            r = rpc_url(OP_CFG["primary"], "eth_getLogs", [q])
            log_calls += 1
            bytes_total += int(r.get("bytes") or 0)
            success = r["outcome"] == "ok" and isinstance(r.get("result"), list)
        elif mode == "always_dual":
            a = rpc_url(OP_CFG["primary"], "eth_getLogs", [q])
            b = rpc_url(dual_fallback, "eth_getLogs", [q])
            log_calls += 2
            bytes_total += int(a.get("bytes") or 0) + int(b.get("bytes") or 0)
            la = a.get("result") if isinstance(a.get("result"), list) else []
            lb = b.get("result") if isinstance(b.get("result"), list) else []
            # Match harness FakeDual: succeed if at least one leg returns a list.
            success = a["outcome"] == "ok" or b["outcome"] == "ok"
            _ = la, lb
        elif mode == "boundaryguard":
            assert proxy_url
            r = rpc_url(proxy_url, "eth_getLogs", [q], timeout=60.0)
            bytes_total += int(r.get("bytes") or 0)
            success = r["outcome"] == "ok" and isinstance(r.get("result"), list)
        else:
            raise ValueError(mode)
        dt = (time.time() - t0) * 1000
        return {"ok": success, "latency_ms": dt}

    t_wall0 = time.time()
    with ThreadPoolExecutor(max_workers=concurrency) as pool:
        futs = [pool.submit(one, q) for q in queries]
        for fut in as_completed(futs):
            got = fut.result()
            latencies.append(got["latency_ms"])
            if got["ok"]:
                ok += 1
            else:
                fail += 1
    wall = time.time() - t_wall0
    latencies.sort()
    n = len(queries)
    bnd_calls = 0
    if stats0 is not None and proxy is not None:
        log_calls = int(proxy.stats.get("audited", 0) - stats0.get("audited", 0)) or log_calls
        bnd_calls = int(proxy.stats.get("boundary_calls", 0) - stats0.get("boundary_calls", 0))
        log_calls = max(log_calls, n)
    elif mode == "boundaryguard":
        bnd_calls = 2 * n
        log_calls = n
    cu = log_calls * LOG_CU + bnd_calls * CALL_CU
    return {
        "mode": mode,
        "concurrency": concurrency,
        "n": n,
        "ok": ok,
        "fail": fail,
        "wall_s": wall,
        "throughput_qps": (n / wall) if wall > 0 else 0.0,
        "completed_qps": (ok / wall) if wall > 0 else 0.0,
        "p50_ms": latencies[len(latencies) // 2] if latencies else None,
        "p95_ms": latencies[min(len(latencies) - 1, int(0.95 * (len(latencies) - 1)))] if latencies else None,
        "p99_ms": latencies[min(len(latencies) - 1, int(0.99 * (len(latencies) - 1)))] if latencies else None,
        "log_calls_est": log_calls,
        "boundary_calls_est": bnd_calls,
        "cu_est": cu,
        "bytes": bytes_total,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--n", type=int, default=64)
    parser.add_argument("--width", type=int, default=8)
    parser.add_argument("--port", type=int, default=18711)
    parser.add_argument(
        "--concurrencies",
        default="1,8",
        help="comma-separated concurrency levels",
    )
    args = parser.parse_args()
    concs = [int(x) for x in args.concurrencies.split(",") if x.strip()]

    mailbox, queries = load_queries(args.n, args.width)
    print(f"mailbox={mailbox} queries={len(queries)} width={args.width}", flush=True)

    cfg = ProxyConfig(
        chain_id="10",
        mailbox=mailbox,
        primary_url=OP_CFG["primary"],
        boundary_url=ARCHIVE[0],
        repair_url=OP_CFG["repair"],
        boundary_urls=ARCHIVE[1:],
        confirmation_depth=20,
        fault_injection=None,
        repair_fault_injection=None,
        trace_path=str(DATA / "concurrent_throughput_proxy_trace.jsonl"),
    )
    DATA.mkdir(parents=True, exist_ok=True)
    if Path(cfg.trace_path).exists():
        Path(cfg.trace_path).unlink()
    server, proxy = harness.start_proxy(cfg, args.port)
    proxy_url = f"http://127.0.0.1:{args.port}"
    dual_fallback = "https://op-pokt.nodies.app"

    rows = []
    try:
        for c in concs:
            for mode in ("unchecked", "always_dual", "boundaryguard"):
                if hasattr(proxy, "stats") and mode == "boundaryguard":
                    # Best-effort cold-ish: clear cache between concurrency levels.
                    if hasattr(proxy, "cache") and hasattr(proxy.cache, "clear"):
                        proxy.cache.clear()
                print(f"== {mode} c={c} ==", flush=True)
                row = run_mode(
                    mode,
                    queries,
                    concurrency=c,
                    proxy_url=proxy_url,
                    dual_fallback=dual_fallback,
                    proxy=proxy if mode == "boundaryguard" else None,
                )
                rows.append(row)
                print(json.dumps(row, sort_keys=True), flush=True)
                time.sleep(0.5)
    finally:
        server.shutdown()

    # Compare BG vs dual throughput at each concurrency.
    by = {(r["mode"], r["concurrency"]): r for r in rows}
    comparisons = []
    for c in concs:
        bg = by.get(("boundaryguard", c))
        dual = by.get(("always_dual", c))
        un = by.get(("unchecked", c))
        if not bg or not dual:
            continue
        comparisons.append(
            {
                "concurrency": c,
                "bg_qps": bg["throughput_qps"],
                "dual_qps": dual["throughput_qps"],
                "unchecked_qps": None if not un else un["throughput_qps"],
                "bg_ok": bg["ok"],
                "dual_ok": dual["ok"],
                "unchecked_ok": None if not un else un["ok"],
                "bg_over_dual_qps": (
                    None if dual["throughput_qps"] <= 0 else bg["throughput_qps"] / dual["throughput_qps"]
                ),
                "bg_p50_ms": bg["p50_ms"],
                "dual_p50_ms": dual["p50_ms"],
                "bg_cu_est": bg["cu_est"],
                "dual_cu_est": dual["cu_est"],
            }
        )

    # Report-only gate: experiment always writes; paper uses c=1 and c=8
    # (higher c saturates public RPCs). Pass if c=1 and c=8 complete and CU(BG)<CU(dual).
    usable = [x for x in comparisons if x["concurrency"] in (1, 8)]
    cu_ok = all(
        (by[("boundaryguard", c)]["cu_est"] < by[("always_dual", c)]["cu_est"]) for c in (1, 8)
        if ("boundaryguard", c) in by and ("always_dual", c) in by
    )
    complete_ok = all(x["bg_ok"] >= int(0.9 * args.n) and x["dual_ok"] >= int(0.9 * args.n) for x in usable)
    ratios = [
        x["bg_over_dual_qps"]
        for x in usable
        if x.get("bg_over_dual_qps") is not None
    ]
    summary = {
        "gate": "concurrent_throughput",
        "provenance": "live_public_rpc_observation",
        "observed_at": datetime.now(timezone.utc).isoformat(),
        "n": args.n,
        "width": args.width,
        "concurrencies": concs,
        "rows": rows,
        "comparisons": comparisons,
        "mean_bg_over_dual_qps_c1_c8": None if not ratios else statistics.fmean(ratios),
        "cu_saving_preserved": cu_ok,
        "pass": complete_ok and cu_ok and bool(usable),
        "note": (
            "Same-host proxy/harness concurrency, not official Hyperlane "
            "single/fallback/quorum agent modes. Complements cold serial Table V. "
            "c>=16 saturates public RPC rate limits; paper cites c=1 and c=8."
        ),
    }
    OUT.write_text(json.dumps(summary, indent=2, sort_keys=True) + "\n")
    print(json.dumps({k: summary[k] for k in summary if k != "rows"}, indent=2, sort_keys=True))
    raise SystemExit(0 if summary["pass"] else 2)


if __name__ == "__main__":
    main()
